ExprDef *append_keysym_list(ExprDef *expr, ExprDef *append) {
    size_t original_size = expr->keysym_count;
    size_t append_size = append->keysym_count;

    // Resize keysym and map arrays in expr to accommodate appended data
    expr->keysym_count += append_size;
    expr->keysym = realloc(expr->keysym, expr->keysym_count * sizeof(*expr->keysym));
    expr->map = realloc(expr->map, expr->keysym_count * sizeof(*expr->map));

    // Copy keysym and map data from append into expr
    for (size_t i = 0; i < append_size; i++) {
        expr->keysym[original_size + i] = append->keysym[i];
        expr->map[original_size + i] = append->map[i];
    }

    // Free memory from append
    free(append->keysym);
    free(append->map);
    free(append);

    return expr;
}

ExprDef *append_keysym_list(ExprDef *expr, ExprDef *append) {
    size_t original_size = expr->keysym_size;
    size_t append_count = append->entry_count;

    expr->keysym_size += append->keysym_size;
    expr->keysym = realloc(expr->keysym, expr->keysym_size * sizeof(*expr->keysym));
    if (!expr->keysym) {
        return NULL;
    }

    size_t expr_entry_count = expr->entry_count;
    expr->entry_count += append_count;
    expr->map = realloc(expr->map, expr->entry_count * sizeof(*expr->map));
    if (!expr->map) {
        free(expr->keysym);
        return NULL;
    }

    for (size_t i = original_size, j = 0; i < expr->keysym_size; i++, j++) {
        expr->keysym[i] = append->keysym[j];
        expr->map[i] += expr_entry_count;
    }

    free(append->keysym);
    free(append->map);
    free(append);

    return expr;
}
